// AI-Personalized Pricing per Visitor
// Dynamically adjusts pricing based on visitor behavior, location, and intent.
// No competing SaaS offers real-time per-visitor AI pricing.

const pricingModel = require('./pricingModel');
const visitorProfile = require('./visitorProfile');

async function getPersonalizedPrice(visitorId, basePrice) {
  const profile = await visitorProfile.get(visitorId);
  let multiplier = 1.0;
  if (profile.intentScore > 0.8) multiplier = 1.2;
  else if (profile.intentScore < 0.3) multiplier = 0.85;
  if (profile.location === 'emerging') multiplier *= 0.9;
  return Math.round(basePrice * multiplier * 100) / 100;
}

module.exports = { getPersonalizedPrice };
